{"files": {"engine.mjs": "export function legalMoves(puzzle, pegs) {
  const pegSet = new Set(pegs);
  const moves = [];
  for (const [fx, fy] of pegs) {
    for (const [dx, dy] of puzzle.directions) {
      const ox = fx + dx, oy = fy + dy;
      const tx = fx + 2 * dx, ty = fy + 2 * dy;
      if (pegSet.has(`${ox},${oy}`) && !pegSet.has(`${tx},${ty}`) && puzzle.cells.includes(`${tx},${ty}`)) {
        moves.push([[fx, fy], [ox, oy], [tx, ty]]);
      }
    }
  }
  return moves;
}

export function applyMove(puzzle, pegs, move) {
  const [from, over, to] = move;
  const fromKey = `${from[0]},${from[1]}`;
  const overKey = `${over[0]},${over[1]}`;
  const toKey = `${to[0]},${to[1]}`;
  const pegSet = new Set(pegs);
  if (!pegSet.has(fromKey) || !pegSet.has(overKey) || pegSet.has(toKey) || !puzzle.cells.includes(toKey)) {
    throw new Error('Illegal move');
  }
  const newPegs = pegs.filter(p => `${p[0]},${p[1]}` !== fromKey && `${p[0]},${p[1]}` !== overKey);
  newPegs.push(to);
  return newPegs;
}

export function isSolved(puzzle, pegs) {
  const goalSet = new Set(puzzle.goal);
  const pegSet = new Set(pegs);
  if (goalSet.size !== pegSet.size) return false;
  for (const p of pegs) {
    if (!goalSet.has(`${p[0]},${p[1]}`)) return false;
  }
  return true;
